// Playful brand sections retain the working studio entry points.
function creativeRibbons(){const line=(text)=>`<span>${text}</span><span aria-hidden="true">${text}</span>`;return `<section class="creative-ribbons" aria-label="아이디어를 한패스 디자인으로"><div class="ribbon-watermark" aria-hidden="true">CREATE SOMETHING GREAT.</div><div class="creative-ribbon ribbon-dark"><div>${line('MAKE IT HANPASS. <i>✳</i> 작은 아이디어, 새로운 가능성. <i>↗</i> ')}</div></div><div class="creative-ribbon ribbon-blue"><div>${line('YOUR NEXT DESIGN <i>✦</i> 오늘의 아이디어를 만들어 보세요. <i>☺</i> ')}</div></div></section>`}
function studioPavilion(){return `<section class="studio-pavilion"><img src="assets/studio-pavilion.png" alt="블루와 라임 컬러의 입체적인 한패스 크리에이티브 스튜디오" loading="lazy"><div class="pavilion-heading"><span>LET’S MAKE IT HAPPEN</span><h2>Next, your idea.</h2><p>다음 디자인의 시작은 당신의 아이디어.</p><button data-easy-nav="request">디자이너에게 도움 요청 <span>↗</span></button></div><footer class="pavilion-footer"><a href="#home">hanpass<span>CREATIVE STUDIO</span></a><p>아이디어부터 완성까지, 함께 만드는 한패스.</p><button data-easy-nav="mine">내 작업으로 ↗</button></footer></section>`}
const playfulHome=homePage;
homePage=function(){let html=playfulHome();html=html.replace('<div id="hpFormats">',creativeRibbons()+'<div id="hpFormats">');html=html.replace('<div class="section-heading"><div><h2>이어서 작업하세요</h2><p>이전 디자인을 복사하면 더 빠르게 시작할 수 있어요.</p></div><button class="ghost" data-easy-nav="mine">내 작업 전체 보기 →</button></div>',`<div class="creative-work-heading"><span class="work-kicker">MADE WITH HANPASS</span><h2>Your next<br><em>great work.</em></h2><span class="work-sticker">MADE BY YOU ↗</span><span class="work-spark" aria-hidden="true">✳</span><div class="work-subline"><p>만들던 디자인, 여기서 이어가세요.</p><button data-easy-nav="mine">내 작업 전체 보기 ↗</button></div></div>`);return html+studioPavilion()};
render();
